const body = $input.item.json.body || $input.item.json;
const ts = new Date().toISOString();
const lead = { name: body.name||'', phone: body.phone||'', email: body.email||'', source: body.source||'unknown', message: body.message||'' };
const agents = ['Jonata','Jaciel','Sidnei'];
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
const db = `${prj}/IMPAR_OS/database/impar.db`;
const { execSync } = require('child_process');
let counter = 0;
try { counter = parseInt(execSync(`sqlite3 "${db}" "SELECT COALESCE(value,0) FROM system_state WHERE key='lead_counter';"`, {timeout:3000}).toString().trim()) || 0; } catch(e) {}
const assigned = agents[counter % agents.length];
counter++;
try { execSync(`sqlite3 "${db}" "INSERT OR REPLACE INTO system_state VALUES ('lead_counter','${counter}','${ts}');"`, {timeout:3000}); } catch(e) {}
return [{ json: { status: 'classified', ai_used: false, timestamp: ts, lead_name: lead.name, source: lead.source, assigned_to: assigned, production_send: false, note: 'DRY-RUN: mensagem NÃO enviada. Ative production_mode para enviar.' } }];
